from collections import Counter

def transform(grid):
    counts = Counter(v for row in grid for v in row)
    background, foreground = counts.most_common(2)[0][0], counts.most_common(2)[1][0]
    if counts[foreground] == 1:
        return [[0 if v == foreground else foreground for v in row] for row in grid]
    return [[background if v == foreground else 0 for v in row] for row in grid]
